const n="// 传统沙箱脚本 - 使用 registerFunction 注册函数\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n\r\n// 页面初始化\r\nconsole.log('📊 堆叠列演示页面已加载 (传统沙箱执行)');\r\nconsole.log('📦 页面数据:', $data);\r\n\r\n// 注册页面函数\r\nregisterFunction('__init__', function() {\r\n  console.log('✅ 堆叠列演示页面已初始化')\r\n});\r\n\r\nregisterFunction('handleToolbarClick', function(args) {\r\n  // 移除导出功能（沙箱环境不支持直接DOM访问）\r\n  console.log('📊 工具栏点击:', args.item.id)\r\n  alert('导出功能在沙箱环境中不可用')\r\n});\r\n\r\nregisterFunction('handleExcelExport', function() {\r\n  // 移除导出功能（沙箱环境不支持直接DOM访问）\r\n  console.log('📊 Excel导出')\r\n  alert('导出功能在沙箱环境中不可用')\r\n});\r\n\r\nregisterFunction('handlePdfExport', function() {\r\n  // 移除导出功能（沙箱环境不支持直接DOM访问）\r\n  console.log('📄 PDF导出')\r\n  alert('导出功能在沙箱环境中不可用')\r\n});\r\n\r\nregisterFunction('handleRowDoubleClick', function(args) {\r\n  console.log('🖱️ 双击行:', args.rowData)\r\n  alert(`订单详情:\\n订单ID: ${args.rowData.OrderID}\\n客户: ${args.rowData.CustomerName}\\n国家: ${args.rowData.ShipCountry}`)\r\n});\r\n\r\nregisterFunction('dataBound', function(args) {\r\n  console.log('✅ 数据绑定完成')\r\n});\r\n\r\nregisterFunction('queryCellInfo', function(args) {\r\n  // 状态列着色\r\n  if (args.column.field === 'Status') {\r\n    if (args.data.Status === 'Delivered') {\r\n      args.cell.classList.add('status-delivered')\r\n    } else if (args.data.Status === 'Shipped') {\r\n      args.cell.classList.add('status-shipped')\r\n    } else if (args.data.Status === 'Processing') {\r\n      args.cell.classList.add('status-processing')\r\n    }\r\n  }\r\n\r\n  // 付款状态着色\r\n  if (args.column.field === 'PaymentStatus') {\r\n    if (args.data.PaymentStatus === 'Paid') {\r\n      args.cell.classList.add('payment-paid')\r\n    } else if (args.data.PaymentStatus === 'Pending') {\r\n      args.cell.classList.add('payment-pending')\r\n    }\r\n  }\r\n});\r\n";export{n as default};
